<template>
  <section class="world-browser">
    <div class="vocabulary-toolbar"><label class="search"><span>搜索词条</span><input v-model="search" type="search" placeholder="名称、说明或属性" /></label><div class="filters" aria-label="词条筛选"><button v-for="option in filters" :key="option.id" :disabled="option.id === 'isolated' && !complete" :aria-pressed="kind===option.id" :class="{active:kind===option.id}" @click="kind=option.id">{{ option.label }}</button></div><span class="result-count">{{ matches.length }} / {{ graph.nodes.length }} 个词条</span></div>
    <p v-if="loading" class="load-status" role="status">正在加载词条资料 {{ loadedCount }} / {{ articles.length }}</p><p v-if="failedIds.length" class="load-error" role="alert">{{ failedIds.length }} 个词条资料加载失败，目录仍可浏览。<button :disabled="loading" @click="loadDetails(true)">重试</button></p>
    <div v-if="network && graph.nodes.length" class="network-layout">
      <div class="network-main"><div class="graph-tools"><span>{{ graph.links.length }} 条关系</span><button aria-label="放大关系图" @click="zoomBy(1.2)">＋</button><button aria-label="缩小关系图" @click="zoomBy(1/1.2)">－</button><button @click="resetView">重置视图</button></div><svg ref="svg" class="world-network" viewBox="0 0 1000 700" aria-label="词条关系图，可拖动和缩放" tabindex="0" @pointerdown="startPan" @pointermove="movePointer" @pointerup="endPointer" @pointercancel="endPointer" @lostpointercapture="endPointer" @wheel.prevent="wheel" @keydown="graphKey">
        <defs><marker :id="markerId" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#a8997d" /></marker><clipPath v-for="node in graph.nodes" :id="clipId(node.id)" :key="node.id"><circle r="26" /></clipPath></defs>
        <g :transform="`translate(${panX},${panY}) scale(${zoom})`"><g v-for="edge in edges" :key="edge.key" :class="{dim:!edgeMatches(edge)}"><path :d="edge.path" fill="none" stroke="#b6aa91" stroke-width="1.4" :marker-end="`url(#${markerId})`" /><text :x="edge.x" :y="edge.y-5" text-anchor="middle" class="relation-label">{{ edge.label }}</text></g>
          <a v-for="node in graph.nodes" :key="node.id" class="world-graph-node" :class="{selected:selectedId===node.id,dim:!matchingIds.has(node.id)}" :href="`/article/${node.id}`" :aria-label="`${node.title}，${node.degree} 条关系`" :transform="nodeTransform(node.id)" @pointerdown.stop="startDrag($event,node.id)" @click="clickNode($event,node.id)" @keydown.enter.prevent="selectedId=node.id"><title>{{ node.title }}</title><circle r="30" class="node-ring" :fill="node.degree ? '#edf0df' : '#f6eee1'" /><image v-if="node.pic && !imageErrors[node.id]" :href="node.pic" x="-26" y="-26" width="52" height="52" :clip-path="`url(#${clipId(node.id)})`" preserveAspectRatio="xMidYMid slice" @error="$set(imageErrors,node.id,true)" /><text v-else text-anchor="middle" dominant-baseline="central" class="node-initial">{{ node.title.slice(0,1) }}</text><text y="49" text-anchor="middle" class="node-title">{{ shortTitle(node.title) }}</text></a>
        </g>
      </svg><p class="graph-hint">拖动词条或空白处，滚轮缩放。点击词条查看资料，右侧可打开正文。</p></div>
      <aside class="selected-vocabulary"><template v-if="selected"><span class="eyebrow">词条资料</span><h3>{{ selected.title }}</h3><p>{{ selected.desc || (selected.loaded ? '暂无词条说明' : '资料加载中…') }}</p><dl v-if="selected.attributes.length"><template v-for="(attr,index) in selected.attributes"><dt :key="`name-${index}`">{{ attr.name }}</dt><dd :key="`value-${index}`">{{ attr.content }}</dd></template></dl><nuxt-link class="read-vocabulary" :to="`/article/${selected.id}`">阅读完整词条 →</nuxt-link><h4>关联词条（{{ selectedEdges.length }}）</h4><ul><li v-for="edge in selectedEdges" :key="edge.key"><button @click="selectedId=edge.other.id">{{ edge.incoming ? '←' : '→' }} {{ edge.other.title }}</button><span>{{ edge.label || '关联' }}</span></li></ul><p v-if="!selectedEdges.length">{{ complete ? '这个词条尚未建立关系。' : '其余关系资料尚在加载。' }}</p></template><p v-else>选择图中的词条，查看说明、属性和关系。</p></aside>
    </div>
    <div class="vocabulary-list-header"><h3>{{ network ? '词条目录' : '世界词条' }}</h3><nuxt-link v-if="!network" :to="`/world/relations/${novelId}`">查看关系网 →</nuxt-link></div>
    <div class="vocabulary-grid"><article v-for="node in matches" :key="node.id" class="vocabulary-entry"><nuxt-link :to="`/article/${node.id}`"><img v-if="node.pic && !imageErrors[node.id]" :src="node.pic" :alt="node.title" loading="lazy" @error="$set(imageErrors,node.id,true)" /><span v-else class="entry-initial">{{ node.title.slice(0,1) }}</span><div><h4>{{ node.title }}</h4><p>{{ node.desc || '查看完整词条' }}</p><small v-if="node.loaded">{{ node.attributes.length }} 项属性 · {{ node.degree }} 条关系</small></div></nuxt-link><button v-if="network" @click="selectAndFocus(node.id)">在图中定位</button></article></div><p v-if="!matches.length" class="empty">{{ articles.length ? '没有符合筛选条件的词条。' : '这个世界尚未添加词条。' }}</p>
  </section>
</template>
<script>
import { worldGraph, filterWorldNodes } from '~/utils/reader-world'
import { graphPositions, graphStep, graphEdge } from '~/utils/world-graph-layout'
export default {
  props:{articles:{type:Array,default:()=>[]},novelId:{type:[Number,String],required:true},network:{type:Boolean,default:false}},
  data(){return{rows:this.articles.slice(),search:'',kind:'all',loading:false,failedIds:[],version:0,loadedCount:0,imageErrors:{},selectedId:0,points:graphPositions(worldGraph(this.articles).nodes),zoom:1,panX:0,panY:0,drag:null,dragMoved:false,iteration:0,filters:[{id:'all',label:'全部'},{id:'connected',label:'有关联'},{id:'isolated',label:'独立词条'},{id:'pictured',label:'有插图'}]}},
  computed:{graph(){return worldGraph(this.rows)},matches(){return filterWorldNodes(this.graph.nodes,{search:this.search,kind:this.kind})},matchingIds(){return new Set(this.matches.map(node=>node.id))},complete(){return !this.loading&&!this.failedIds.length&&this.graph.nodes.every(node=>node.loaded)},selected(){return this.graph.nodes.find(node=>node.id===this.selectedId)},markerId(){return`world-arrow-${this.novelId}`},positionMap(){return new Map(this.points.map(point=>[point.id,point]))},edges(){return this.graph.links.map(link=>({...link,...graphEdge(this.positionMap.get(link.source),this.positionMap.get(link.target))}))},selectedEdges(){return this.graph.links.filter(edge=>edge.source===this.selectedId||edge.target===this.selectedId).map(edge=>({...edge,incoming:edge.target===this.selectedId,other:this.graph.nodes.find(node=>node.id===(edge.source===this.selectedId?edge.target:edge.source))}))}},
  watch:{articles(){this.resetData()},novelId(){this.resetData()},graph(){this.syncPoints()},network(value){if(value)this.animate();else this.stopAnimation()}},
  mounted(){this.loadDetails();if(this.network)this.animate()},beforeDestroy(){this.version++;this.stopAnimation();this.drag=null},
  methods:{
    resetData(){this.version++;this.stopAnimation();this.rows=this.articles.slice();this.failedIds=[];this.imageErrors={};this.selectedId=0;this.loadedCount=0;this.loading=false;this.kind='all';this.resetView();this.points=graphPositions(worldGraph(this.rows).nodes);this.loadDetails()},
    async loadDetails(retry=false){if(this.loading)return;const version=++this.version,novelId=Number(this.novelId);this.loading=true;const pending=this.articles.filter(article=>retry?this.failedIds.includes(Number(article.article_id)):!this.rows.some(row=>Number(row.article_id)===Number(article.article_id)&&Object.prototype.hasOwnProperty.call(row,'content')));this.failedIds=retry?this.failedIds.filter(id=>!pending.some(row=>Number(row.article_id)===id)):[]
      for(let i=0;i<pending.length;i+=5){const batch=await Promise.all(pending.slice(i,i+5).map(async article=>{try{const response=await this.$api.reader.article(article.article_id),detail=response&&response[0];if(!detail||Number(detail.article_id)!==Number(article.article_id)||Number(detail.novel_id)!==novelId||detail.article_type!=='worldVocabulary'||Number(detail.is_draft)===1)throw new Error('词条不可阅读');return{detail}}catch(_){return{failed:Number(article.article_id)}}}));if(version!==this.version||novelId!==Number(this.novelId))return;for(const result of batch){if(result.failed)this.failedIds.push(result.failed);else{const index=this.rows.findIndex(row=>Number(row.article_id)===Number(result.detail.article_id));if(index>=0)this.$set(this.rows,index,{...result.detail})}}this.loadedCount=this.rows.filter(row=>Object.prototype.hasOwnProperty.call(row,'content')).length}
      if(version===this.version)this.loading=false
    },
    syncPoints(){const old=this.positionMap;this.points=graphPositions(this.graph.nodes).map(point=>old.get(point.id)||point);if(this.network)this.animate()},
    stopAnimation(){if(this.frame)cancelAnimationFrame(this.frame);this.frame=null},
    animate(){this.stopAnimation();if(!this.network||!this.points.length||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;this.iteration=0;const step=()=>{this.frame=null;if(!this.network)return;graphStep(this.points,this.graph.links,this.drag&&this.drag.id,this.iteration++);if(this.iteration<240)this.frame=requestAnimationFrame(step)};this.frame=requestAnimationFrame(step)},
    nodeTransform(id){const point=this.positionMap.get(id);return point?`translate(${point.x},${point.y})`:''},clipId(id){return`world-node-${this.novelId}-${id}`},shortTitle(title){return title.length>12?title.slice(0,11)+'…':title},edgeMatches(edge){return this.matchingIds.has(edge.source)||this.matchingIds.has(edge.target)},
    zoomBy(factor,x=500,y=350){const next=Math.max(.35,Math.min(3,this.zoom*factor)),ratio=next/this.zoom;this.panX=x+(this.panX-x)*ratio;this.panY=y+(this.panY-y)*ratio;this.zoom=next},resetView(){this.zoom=1;this.panX=this.panY=0},
    svgPoint(event){const rect=this.$refs.svg.getBoundingClientRect();return{x:(event.clientX-rect.left)*1000/rect.width,y:(event.clientY-rect.top)*700/rect.height}},
    wheel(event){const point=this.svgPoint(event);this.zoomBy(event.deltaY<0?1.1:1/1.1,point.x,point.y)},
    startPan(event){if(event.button!==0)return;const point=this.svgPoint(event);this.drag={id:0,x:point.x,y:point.y,panX:this.panX,panY:this.panY};this.dragMoved=false;event.currentTarget.setPointerCapture?.(event.pointerId)},
    startDrag(event,id){if(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;const point=this.svgPoint(event),node=this.positionMap.get(id);this.drag={id,x:point.x,y:point.y,nodeX:node.x,nodeY:node.y};this.dragMoved=false;event.currentTarget.setPointerCapture?.(event.pointerId)},
    movePointer(event){if(!this.drag)return;const point=this.svgPoint(event),dx=point.x-this.drag.x,dy=point.y-this.drag.y;if(Math.abs(dx)+Math.abs(dy)>4)this.dragMoved=true;if(this.drag.id){const node=this.positionMap.get(this.drag.id);node.x=Math.max(40,Math.min(960,this.drag.nodeX+dx/this.zoom));node.y=Math.max(40,Math.min(660,this.drag.nodeY+dy/this.zoom))}else{this.panX=this.drag.panX+dx;this.panY=this.drag.panY+dy}},
    endPointer(){if(!this.drag)return;this.drag=null;this.animate()},
    clickNode(event,id){if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();if(this.dragMoved){this.dragMoved=false;return}this.selectedId=id},
    selectAndFocus(id){this.selectedId=id;const point=this.positionMap.get(id);this.panX=500-point.x*this.zoom;this.panY=350-point.y*this.zoom;this.$nextTick(()=>this.$refs.svg?.focus())},
    graphKey(event){if(event.target!==event.currentTarget)return;const movement={ArrowLeft:[30,0],ArrowRight:[-30,0],ArrowUp:[0,30],ArrowDown:[0,-30]}[event.key];if(movement){event.preventDefault();this.panX+=movement[0];this.panY+=movement[1]}else if(event.key==='+'||event.key==='='){event.preventDefault();this.zoomBy(1.2)}else if(event.key==='-'){event.preventDefault();this.zoomBy(1/1.2)}else if(event.key==='Home'){event.preventDefault();this.resetView()}}
  }
}
</script>
<style scoped>
.world-browser{min-width:0}.vocabulary-toolbar{display:flex;align-items:flex-end;gap:16px;flex-wrap:wrap;margin:0 0 20px}.search{display:grid;gap:7px;flex:1;min-width:190px;max-width:360px;font-size:12px;color:#8c7a64}.search input{width:100%;box-sizing:border-box;border:1px solid #ded5c8;border-radius:7px;padding:10px 12px;font:inherit;font-size:14px;color:#655944;background:#fff}.filters{display:flex;gap:6px;flex-wrap:wrap}.filters button,.graph-tools button,.vocabulary-entry button{border:1px solid #e4ddcf;border-radius:6px;background:#fff;color:#8d7759;padding:8px 11px;font:inherit;font-size:12px;cursor:pointer}.filters .active{background:#eaf0dd;color:#738748;border-color:#d6e0bf}button:disabled{opacity:.45;cursor:default}.result-count{font-size:12px;color:#a09687;margin-left:auto;line-height:34px}.load-status,.load-error{font-size:12px;line-height:1.8;margin:10px 0 16px;color:#a18e70}.load-error{color:#b3624c}.load-error button{background:none;border:0;color:inherit;text-decoration:underline;cursor:pointer}.network-layout{display:grid;grid-template-columns:minmax(0,1fr) 265px;border:1px solid #e5ddcd;border-radius:12px;overflow:hidden;margin-bottom:28px}.network-main{min-width:0;background:#faf9f5}.graph-tools{display:flex;align-items:center;gap:6px;padding:14px 18px;position:relative;z-index:1}.graph-tools span{margin-right:auto;font-size:12px;color:#a2927a}.world-network{display:block;width:100%;aspect-ratio:10/7;touch-action:none;background-image:radial-gradient(#ddd5c5 1px,transparent 1px);background-size:22px 22px}.dim{opacity:.15}.node-ring{stroke:#d5cab3;stroke-width:2}.selected .node-ring{stroke:#7e9655;stroke-width:4}.world-graph-node{cursor:grab}.world-graph-node:active{cursor:grabbing}.world-graph-node:focus .node-ring{stroke:#7e9655;stroke-width:4}.node-initial{font-size:22px;fill:#88765b}.node-title{font-size:16px;fill:#6e614e;paint-order:stroke;stroke:#faf9f5;stroke-width:5px}.relation-label{font-size:13px;fill:#9b896b;paint-order:stroke;stroke:#faf9f5;stroke-width:4px}.graph-hint{padding:0 18px 16px;font-size:11px;color:#aa9b83;line-height:1.8}.selected-vocabulary{padding:24px;border-left:1px solid #e5ddcd;min-width:0;max-height:650px;overflow:auto;background:#fff;overflow-wrap:anywhere}.eyebrow{font-size:11px;letter-spacing:2px;color:#a5967e}.selected-vocabulary h3{font-size:20px;margin:10px 0 16px;color:#665a45}.selected-vocabulary p{font-size:13px;line-height:1.8;color:#a09077;white-space:pre-wrap}.selected-vocabulary dl{font-size:12px;margin:18px 0}.selected-vocabulary dt{color:#a39378;margin-top:12px}.selected-vocabulary dd{margin:5px 0 0;color:#6f624b;white-space:pre-wrap}.read-vocabulary{display:inline-block;margin:18px 0;color:#7b9054;font-size:13px;text-decoration:none}.selected-vocabulary h4{font-size:13px;color:#938169;margin:16px 0}.selected-vocabulary ul{list-style:none;padding:0}.selected-vocabulary li{border-bottom:1px solid #eee8df;padding:9px 0;display:grid;gap:5px}.selected-vocabulary li button{text-align:left;border:0;background:none;color:#7c8d51;font:inherit;font-size:12px;cursor:pointer;padding:0}.selected-vocabulary li span{font-size:11px;color:#b09f83}.vocabulary-list-header{display:flex;justify-content:space-between;align-items:center;margin:12px 0 18px}.vocabulary-list-header h3{font-size:17px;color:#7a6850}.vocabulary-list-header a{font-size:13px;color:#859555;text-decoration:none}.vocabulary-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.vocabulary-entry{min-width:0;border:1px solid #e7e0d5;border-radius:9px;background:#fff;overflow:hidden}.vocabulary-entry a{display:flex;gap:12px;padding:16px;text-decoration:none;min-width:0;color:inherit}.vocabulary-entry img,.entry-initial{width:42px;height:42px;border-radius:8px;object-fit:cover;flex-shrink:0}.entry-initial{display:flex;align-items:center;justify-content:center;background:#edf0e2;color:#8a9a60;font-size:20px}.vocabulary-entry a div{min-width:0}.vocabulary-entry h4{font-size:14px;color:#776247;margin:1px 0 7px;overflow-wrap:anywhere}.vocabulary-entry p{font-size:12px;color:#a79781;line-height:1.7;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0}.vocabulary-entry small{font-size:10px;color:#afa087;display:block;margin-top:8px}.vocabulary-entry>button{display:block;font-size:11px;margin:0 16px 14px}.empty{font-size:13px;text-align:center;padding:40px;color:#a69982}button:focus-visible,input:focus-visible,a:focus-visible,svg:focus-visible{outline:2px solid #8a9b62;outline-offset:3px}@media(max-width:1000px){.vocabulary-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.network-layout{grid-template-columns:1fr}.selected-vocabulary{border-left:0;border-top:1px solid #e5ddcd;max-height:300px}.graph-hint{font-size:12px}}@media(max-width:600px){.vocabulary-grid{grid-template-columns:1fr}.result-count{margin-left:0}.vocabulary-toolbar{gap:10px}.vocabulary-entry a{padding:14px}}
</style>
